// Buat tabel sensor_history
msg.topic = "CREATE TABLE IF NOT EXISTS sensor_history (id INTEGER PRIMARY KEY AUTOINCREMENT, suhu REAL, kelembaban REAL, timestamp TEXT, received TEXT)";
return msg;

var val = 30.0;
if (msg.payload && msg.payload.length > 0) {
    val = msg.payload[0].value;
}
flow.set('threshold', val);
flow.set('lamp_status', 'off');
node.warn('DB Initialized. Threshold: ' + val + '°C');
return msg;

var data = msg.payload;
var suhu = data.suhu;
var kelembaban = data.kelembaban;
var timestamp = data.timestamp;
var received = new Date().toISOString();
var threshold = flow.get('threshold') || 30.0;
var lamp = flow.get('lamp_status') || 'off';

// Simpan data terakhir di flow context
flow.set('last_sensor', {
    suhu: suhu,
    kelembaban: kelembaban,
    timestamp: timestamp,
    received: received
});

// Message untuk simpan ke SQLite
var msgDb = {
    topic: "INSERT INTO sensor_history (suhu, kelembaban, timestamp, received) VALUES (" + suhu + ", " + kelembaban + ", '" + timestamp + "', '" + received + "')"
};

// Cek threshold
var isAlert = suhu > threshold;

// Message untuk WebSocket broadcast
var msgWs = {
    payload: JSON.stringify({
        type: 'sensor',
        suhu: suhu,
        kelembaban: kelembaban,
        timestamp: timestamp,
        threshold: threshold,
        alert: isAlert,
        lamp: lamp
    })
};

// Message untuk alert (jika threshold terlampaui)
var msgAlert = null;
if (isAlert) {
    msgAlert = {
        payload: JSON.stringify({
            type: 'alert',
            message: 'PERINGATAN: Suhu ' + suhu + '°C melewati batas ' + threshold + '°C!',
            suhu: suhu,
            threshold: threshold,
            timestamp: timestamp
        })
    };
}

return [msgDb, msgWs, msgAlert];

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'
};
msg.statusCode = 204;
msg.payload = '';
return msg;

var apiKey = msg.req.headers['x-api-key'];
var validKey = 'uniska-iot-2026';

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key',
    'Content-Type': 'application/json'
};

if (!apiKey || apiKey !== validKey) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Invalid or missing X-API-Key' };
    return [null, msg];
}
return [msg, null];

var threshold = flow.get('threshold') || 30.0;
var data = msg.payload;

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key',
    'Content-Type': 'application/json'
};

if (data && data.length > 0) {
    var row = data[0];
    msg.payload = {
        status: 'success',
        data: {
            suhu: row.suhu,
            kelembaban: row.kelembaban,
            timestamp: row.timestamp,
            threshold: threshold,
            alert: row.suhu > threshold
        }
    };
} else {
    msg.payload = {
        status: 'success',
        data: null,
        message: 'Belum ada data sensor'
    };
}
return msg;

var apiKey = msg.req.headers['x-api-key'];
var validKey = 'uniska-iot-2026';

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key',
    'Content-Type': 'application/json'
};

if (!apiKey || apiKey !== validKey) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Invalid or missing X-API-Key' };
    return [null, msg];
}
return [msg, null];

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key',
    'Content-Type': 'application/json'
};

msg.payload = {
    status: 'success',
    count: msg.payload.length,
    data: msg.payload
};
return msg;

var apiKey = msg.req.headers['x-api-key'];
var validKey = 'uniska-iot-2026';

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key',
    'Content-Type': 'application/json'
};

if (!apiKey || apiKey !== validKey) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Invalid or missing X-API-Key' };
    return [null, msg];
}
return [msg, null];

var body = msg.payload;

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key',
    'Content-Type': 'application/json'
};

// Validasi input
if (!body.device || !body.action) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'Field device dan action wajib diisi' };
    return [null, msg, null];
}

if (body.device !== 'lamp') {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'Device tidak dikenal. Gunakan: lamp' };
    return [null, msg, null];
}

if (body.action !== 'on' && body.action !== 'off') {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'Action harus on atau off' };
    return [null, msg, null];
}

// Simpan status lampu di flow context
flow.set('lamp_status', body.action);

// Message untuk MQTT
var msgMqtt = {
    payload: JSON.stringify({ device: body.device, action: body.action })
};

// Message untuk WebSocket broadcast
var msgWs = {
    payload: JSON.stringify({
        type: 'kontrol',
        device: body.device,
        action: body.action,
        message: 'Lampu ' + (body.action === 'on' ? 'dinyalakan' : 'dimatikan')
    })
};

// Message untuk HTTP response
var msgResp = {
    headers: msg.headers,
    payload: {
        status: 'success',
        message: 'Perintah dikirim ke ' + body.device,
        data: { device: body.device, action: body.action }
    }
};

return [msgMqtt, msgResp, msgWs];

var apiKey = msg.req.headers['x-api-key'];
var validKey = 'uniska-iot-2026';

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key',
    'Content-Type': 'application/json'
};

if (!apiKey || apiKey !== validKey) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Invalid or missing X-API-Key' };
    return [null, msg];
}
return [msg, null];

var body = msg.payload;

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key',
    'Content-Type': 'application/json'
};

// Validasi
var threshold = parseFloat(body.threshold);
if (isNaN(threshold)) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'Nilai threshold harus berupa angka' };
    return [null, msg, null];
}

if (threshold < 0 || threshold > 100) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'Threshold harus antara 0 dan 100' };
    return [null, msg, null];
}

// Simpan ke flow context
flow.set('threshold', threshold);

// Message untuk update database
var msgDb = {
    topic: "UPDATE settings SET value = " + threshold + " WHERE key = 'threshold'"
};

// Message untuk HTTP response
var msgResp = {
    headers: msg.headers,
    payload: {
        status: 'success',
        message: 'Threshold berhasil diperbarui',
        data: { threshold: threshold }
    }
};

// Message untuk WebSocket broadcast
var msgWs = {
    payload: JSON.stringify({
        type: 'threshold',
        threshold: threshold,
        message: 'Threshold diperbarui menjadi ' + threshold + '°C'
    })
};

return [msgDb, msgResp, msgWs];
